    window.detectStaff = function() // Returns 1 if a staff member is found in the userlist
    {
        var listranks = document.getElementsByClassName("list_rank")
        var chatranks = document.getElementsByClassName("chat_rank")
        for(var i=0; i<listranks.length; i++)
        {
            if(listranks[i].src == "https://www.chat-avenue.com/teen/default_images/rank/admin.svg") {return 1}
            if(listranks[i].src == "https://www.chat-avenue.com/teen/default_images/rank/mod.svg") {return 1}
            if(listranks[i].src == "https://www.chat-avenue.com/teen/default_images/rank/owner.svg") {return 1}
            if(listranks[i].src == "https://www.chat-avenue.com/teen/default_images/rank/super.svg") {return 1}
        }
        for(i=0; i<chatranks.length; i++)
        {
            if(chatranks[i].src == "https://www.chat-avenue.com/teen/default_images/rank/admin.svg") {return 1}
            if(chatranks[i].src == "https://www.chat-avenue.com/teen/default_images/rank/mod.svg") {return 1}
            if(chatranks[i].src == "https://www.chat-avenue.com/teen/default_images/rank/owner.svg" && chatranks[i].getAttribute("fake") != "1") {return 1}
            if(chatranks[i].src == "https://www.chat-avenue.com/teen/default_images/rank/super.svg") {return 1}
        }
        return 0;
    }

    window.blurrifyText = function(string) // Turns strings of messages into ones that can evade the censor
    {                                      // They look like they're being replaced with the same character but they're not ;)
        var newstring = string
        newstring = newstring.replaceAll("a","͏a") // These special characters take up more bytes than regular ones,
        newstring = newstring.replaceAll("e","͏e") // thus lowering the allowed message length, to minimize this we
        newstring = newstring.replaceAll("i","͏i") // only replace the vowels
        newstring = newstring.replaceAll("o","͏o")
        newstring = newstring.replaceAll("u","͏u")
        return newstring
    }

    window.toggleCensorBypass = function()
    {
        if(!window.censorBypassOn){
            callSaved("censorBypass enabled.", 1)
        }
        else {
            callSaved("censorBypass disabled.", 3)
        }
        window.censorBypassOn = !window.censorBypassOn
    }

    window.antiSpamLoop = function()
    {
        // Scan page for all messages and place into array
        var messages = document.getElementsByClassName("cavatar")

        // For every message scanned, check if it meets the block criteria
        for(var i=0; i<messages.length; i++)
        {
        // Check if an allowed exception
        if(!(messages[i].parentElement.parentElement.children[1].innerText.includes(window.username)) || window.allowAddressed == false)
        {
            // Check if from guest
            if (messages[i].src == "https://www.chat-avenue.com/teen/default_images/avatar/default_guest.png" && window.blockGuests == true)
            {messages[i].parentElement.parentElement.remove()}

            // Check if from ad bot
            else if (messages[i].src == "https://www.chat-avenue.com/teen/default_images/avatar/default_bot.png" && window.blockAds == true)
            {messages[i].parentElement.parentElement.remove()}

            // Check if from system
            else if (messages[i].src == "https://www.chat-avenue.com/teen/default_images/avatar/default_system.png" && window.blockSystem == true)
            {messages[i].parentElement.parentElement.remove()}
        }
      }
    }

