    processChatPost = function(message){ //Redefine the processChatPost function to incorporate censorBypass
	$.post('system/chat_process.php', {
		content: censorBypassOn? blurrifyText(message): message,
		snum: snum,
		token: utk,
		}, function(response) {
			if(response == ''){
			}
			else if (response == 100){
				checkRm(2);
			}
			else{
				$('#name').val('');
				$("#show_chat ul").append(response);
				scrollIt(0);
			}
			waitReply = 0;
	    });
    }

